// Pega o Csv como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const item = $input.first().json;

const clientes = item.body?.clientes ?? item.clientes ?? [];
const investimentos = item.body?.investimentos ?? item.investimentos ?? [];

function parseSaldo(saldoTexto) {
  if (!saldoTexto) return 0;
  const num = String(saldoTexto).replace(/[^\d,]/g, "").replace(",", ".");
  return parseFloat(num) || 0;
}

function parseRentabilidade(r) {
  return parseFloat(String(r).replace(/[^\d.,]/g, "").replace(",", ".")) || 0;
}

function formatMoeda(valor) {
  return valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function pick(mensagens) {
  return mensagens[Math.floor(Math.random() * mensagens.length)];
}

function gerarMensagens(nome, perfil, saldoTexto, escolhido, motivo) {
  const primeiroNome = (nome || "").split(" ")[0];

  if (!escolhido) {
    return [
      `Olá ${primeiroNome}, no momento não encontramos uma opção de investimento cadastrada para o seu perfil (${perfil}).`,
      `Oi ${primeiroNome}, ainda não temos um produto compatível com seu perfil (${perfil}) na nossa base.`,
      `${primeiroNome}, por enquanto não há recomendação disponível para o perfil ${perfil}.`
    ];
  }

  const minimoTexto = formatMoeda(escolhido.minimo || 0);
  const statusSaldo = motivo === "saldo_ok" ? "já consegue investir" : "ainda precisa complementar o valor";

  return [
    `Olá ${primeiroNome}! Pelo seu perfil (${perfil}), uma boa opção é **${escolhido.produto}** (mínimo ${minimoTexto}). Com seu saldo atual (${saldoTexto}), você ${statusSaldo}. Rentabilidade: ${escolhido.rentabilidade}.`,
    `Oi ${primeiroNome}! Recomendação para perfil ${perfil}: **${escolhido.produto}** (mínimo ${minimoTexto}). Seu saldo (${saldoTexto}) ${motivo === "saldo_ok" ? "já atende o mínimo" : "ainda está abaixo do mínimo"}. Rentabilidade: ${escolhido.rentabilidade}.`,
    `${primeiroNome}, indo direto ao ponto: para o perfil ${perfil}, **${escolhido.produto}** (mínimo ${minimoTexto}). Você tem ${saldoTexto}, então ${motivo === "saldo_ok" ? "dá pra aplicar" : "falta um pouco pra bater o mínimo"}. Rentabilidade: ${escolhido.rentabilidade}.`
  ];
}

const resultados = clientes.map(c => {
  const nome = c.nome;
  const email = c.email;
  const perfil = c.perfil;
  const saldoNum = parseSaldo(c.saldo);

  const opcoesPerfil = investimentos.filter(inv =>
    (inv.perfil || "").toLowerCase().trim() === (perfil || "").toLowerCase().trim()
  );
  const opcoesElegiveis = opcoesPerfil.filter(inv => saldoNum >= (inv.minimo || 0));

  let escolhido = null;
  let motivo = "sem_opcao";

  if (opcoesElegiveis.length > 0) {
    escolhido = opcoesElegiveis.reduce((melhor, atual) =>
      parseRentabilidade(atual.rentabilidade) > parseRentabilidade(melhor.rentabilidade) ? atual : melhor
    );
    motivo = "saldo_ok";
  } else if (opcoesPerfil.length > 0) {
    escolhido = opcoesPerfil.reduce((maisBarata, atual) =>
      (atual.minimo || 0) < (maisBarata.minimo || 0) ? atual : maisBarata
    );
    motivo = "saldo_insuficiente";
  }

  const mensagens = gerarMensagens(nome, perfil, c.saldo, escolhido, motivo);

  return {
    nome,
    email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens),
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

