const items = $input.all();

// Converte texto simples em HTML formatado pro Gmail
function formatarHtmlGmail(texto, htmlOriginal) {
  // Se a IA já mandou um html_body decente, só garante a estrutura básica
  if (htmlOriginal && htmlOriginal.trim().length > 0) {
    return `<div style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6; color: #333;">${htmlOriginal}</div>`;
  }

  // Senão, monta o HTML a partir do texto puro, convertendo quebras de linha
  const paragrafos = String(texto || "")
    .split(/\n{2,}/)
    .map(p => p.trim())
    .filter(Boolean)
    .map(p => `<p>${p.replace(/\n/g, "<br>")}</p>`)
    .join("\n");

  return `<div style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6; color: #333;">${paragrafos}</div>`;
}

const out = items.map((item, index) => {
  const j = $('Code in JavaScript2').all()[index].json;

  const raw = item.json.output?.[0]?.content?.[0]?.text
    ?? item.json.message?.content
    ?? item.json.content
    ?? "";

  const cleanText = String(raw).replace(/```json|```/g, "").trim();

  let parsed = {};
  try {
    parsed = JSON.parse(cleanText);
  } catch (e) {
    parsed = { subject: "", text_body: cleanText, html_body: "" };
  }

  const to = j.email_to || "";
  const subject = parsed.subject || `Oportunidade de investimento para ${j.nome || "você"}`;
  const text_body = parsed.text_body || "";
  const html_body = formatarHtmlGmail(text_body, parsed.html_body);

  return {
    json: {
      ok: true,
      to,
      subject,
      text_body,
      html_body,

      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});

return out;
